import{c as e,S as l,j as a,m as d}from"./chunks/framework.DBSVVeOL.js";const y=JSON.parse('{"title":"Feature Coverage","description":"","frontmatter":{},"headers":[],"relativePath":"feature-coverage.md","filePath":"feature-coverage.md","lastUpdated":null}'),s={name:"feature-coverage.md"};function r(i,t,n,o,c,p){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="Feature-Coverage" tabindex="-1">Feature Coverage <a class="header-anchor" href="#Feature-Coverage" aria-label="Permalink to &quot;Feature Coverage {#Feature-Coverage}&quot;">​</a></h1><p>This page tracks what Natter.jl supports today and what is intentionally still outside the first implementation.</p><p>Statuses:</p><ul><li><p><code>Supported</code>: implemented for the normal production path and tested where practical.</p></li><li><p><code>Partial</code>: usable for common paths, with remaining hardening or API coverage work.</p></li><li><p><code>Planned</code>: intended for future work.</p></li><li><p><code>Not planned</code>: intentionally excluded for now.</p></li></ul><h2 id="Core-NATS" tabindex="-1">Core NATS <a class="header-anchor" href="#Core-NATS" aria-label="Permalink to &quot;Core NATS {#Core-NATS}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">TCP transport</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Plain <code>nats://</code> connections.</td></tr><tr><td style="text-align:left;">TLS transport</td><td style="text-align:left;">Supported</td><td style="text-align:left;">TLS-first, INFO-first upgrade, CA path, certificate verification controls, and client cert/key paths.</td></tr><tr><td style="text-align:left;">WebSocket transport</td><td style="text-align:left;">Planned</td><td style="text-align:left;"><code>ws://</code> and <code>wss://</code> are not implemented.</td></tr><tr><td style="text-align:left;">Connect handshake</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Client name, no echo, server INFO parsing, TLS requirements, and typed auth.</td></tr><tr><td style="text-align:left;">Authentication</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Token, user/password, NKEY, JWT, <code>.creds</code>, callback auth, and URL userinfo for token/user-password.</td></tr><tr><td style="text-align:left;">PUB / HPUB / SUB / UNSUB</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Core publish, headers, queue groups, unsubscribe limits, and local subject validation.</td></tr><tr><td style="text-align:left;">MSG / HMSG parsing</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Core data and headers.</td></tr><tr><td style="text-align:left;">Wildcards</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Subscription wildcards are validated; publish subjects reject wildcards.</td></tr><tr><td style="text-align:left;">Request/reply</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Shared inbox mux, timeouts, and <code>NoRespondersError</code> when supported by the server.</td></tr><tr><td style="text-align:left;">Flush and ping</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>flush</code>/<code>ping</code> use a server round trip.</td></tr><tr><td style="text-align:left;">Drain and close</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Subscription/client drain and deterministic close paths.</td></tr><tr><td style="text-align:left;">Reconnect</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Automatic reconnect, discovered servers, subscription replay, bounded publish replay, lifecycle events, and delay callbacks are implemented. Broader cluster chaos and auth failover hardening remain.</td></tr><tr><td style="text-align:left;">Publish replay</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Buffered core publishes are replayed best-effort and can duplicate after ambiguous network failures. Use JetStream <code>msg_id</code> for durable idempotent publish paths.</td></tr><tr><td style="text-align:left;">Slow consumer handling</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Per-subscription pending limits report <code>SlowConsumerError</code>.</td></tr><tr><td style="text-align:left;">Runtime inspection</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>status</code>, <code>stats</code>, and <code>connected_url</code>.</td></tr><tr><td style="text-align:left;">Async handles</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Public <code>_async</code> helpers return <code>NatterTask</code>; blocking calls accept cooperative cancellation tokens and async handles rethrow <code>CancelledError</code> from cancelled operations.</td></tr></tbody></table><h2 id="JetStream" tabindex="-1">JetStream <a class="header-anchor" href="#JetStream" aria-label="Permalink to &quot;JetStream {#JetStream}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Context</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>jetstream(client)</code>.</td></tr><tr><td style="text-align:left;">Publish ack</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>js_publish</code> returns <code>PubAck</code> and exposes common dedupe, optimistic constraint, TTL, schedule, and retry options.</td></tr><tr><td style="text-align:left;">Stream management</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Create, update, info, list, names, purge, delete.</td></tr><tr><td style="text-align:left;">Typed stream config</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>StreamConfig</code> plus nested helpers and raw <code>Dict</code> escape hatch.</td></tr><tr><td style="text-align:left;">Message lookup</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Sequence, last-by-subject, next-by-subject, direct get, and message delete.</td></tr><tr><td style="text-align:left;">Consumer management</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Create, create-or-update, update, info, list, delete.</td></tr><tr><td style="text-align:left;">Typed consumer config</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>ConsumerConfig</code> plus raw <code>Dict</code> escape hatch.</td></tr><tr><td style="text-align:left;">Pull consumers</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Durable/named bind, ephemeral create/delete, bounded <code>fetch</code>, <code>max_bytes</code>, <code>no_wait</code>, heartbeats, <code>messages</code>, <code>consume</code>, and priority request fields.</td></tr><tr><td style="text-align:left;">Push consumers</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Durable/ephemeral push, queue groups, callbacks, manual/auto ack, flow control replies, and heartbeat reporting. Additional chaos testing remains.</td></tr><tr><td style="text-align:left;">Acknowledgements</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, <code>term</code>.</td></tr><tr><td style="text-align:left;">Metadata</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Delivery metadata parsing.</td></tr><tr><td style="text-align:left;">Ordered consumers</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Used internally for KeyValue watch; no public ordered-consumer helper yet.</td></tr><tr><td style="text-align:left;">Object Store</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Not implemented.</td></tr><tr><td style="text-align:left;">Services/Micro</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Not implemented.</td></tr><tr><td style="text-align:left;">Stream templates and admin APIs</td><td style="text-align:left;">Not planned</td><td style="text-align:left;">Legacy or administrative APIs are not prioritized for client v1.</td></tr></tbody></table><h2 id="KeyValue" tabindex="-1">KeyValue <a class="header-anchor" href="#KeyValue" aria-label="Permalink to &quot;KeyValue {#KeyValue}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Bucket lifecycle</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Create, open, delete, status.</td></tr><tr><td style="text-align:left;">Bucket options</td><td style="text-align:left;">Supported</td><td style="text-align:left;">History, TTL, max bytes, max value size, storage, replicas, direct reads, compression, metadata, and delete-marker TTL.</td></tr><tr><td style="text-align:left;">Get/put/create/update</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Typed entries, optimistic revision checks, per-key TTL, and typed conflict errors.</td></tr><tr><td style="text-align:left;">Delete/purge</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Delete markers, purge markers, guarded delete/purge, and marker cleanup.</td></tr><tr><td style="text-align:left;">History and keys</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Common paths implemented; broader large-bucket stress coverage remains.</td></tr><tr><td style="text-align:left;">Watch</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Channel and callback watchers, filters, updates-only, history, ignore deletes, metadata-only, resume revision, and ordered-consumer recovery. More chaos testing remains.</td></tr><tr><td style="text-align:left;">Direct get</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>direct=true</code> buckets use direct reads by default.</td></tr><tr><td style="text-align:left;">Async handles</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Bucket, key, history, keys, watch, and close helpers.</td></tr></tbody></table><h2 id="Observability-And-Errors" tabindex="-1">Observability And Errors <a class="header-anchor" href="#Observability-And-Errors" aria-label="Permalink to &quot;Observability And Errors {#Observability-And-Errors}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Status</th><th style="text-align:left;">Notes</th></tr></thead><tbody><tr><td style="text-align:left;">Typed errors</td><td style="text-align:left;">Supported</td><td style="text-align:left;">Core, connection, auth, permission, slow consumer, JetStream, fetch, and KeyValue errors.</td></tr><tr><td style="text-align:left;">Lifecycle callbacks</td><td style="text-align:left;">Supported</td><td style="text-align:left;"><code>event_cb</code>, <code>error_cb</code>, and <code>reconnect_delay_cb</code>.</td></tr><tr><td style="text-align:left;">Stats</td><td style="text-align:left;">Partial</td><td style="text-align:left;">Opt-in message, byte, reconnect, error, and dropped-message counters via <code>record_stats=true</code>.</td></tr><tr><td style="text-align:left;">Structured logging facade</td><td style="text-align:left;">Planned</td><td style="text-align:left;">Use callbacks and normal Julia logging for now.</td></tr></tbody></table><h2 id="Test-Modes" tabindex="-1">Test Modes <a class="header-anchor" href="#Test-Modes" aria-label="Permalink to &quot;Test Modes {#Test-Modes}&quot;">​</a></h2><p>The normal package test suite is server-free:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span></span></code></pre></div><p>Real-server tests are opt-in:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">env</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NATTER_RUN_INTEGRATION=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NATTER_RUN_JETSTREAM=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;using Pkg; Pkg.test()&#39;</span></span></code></pre></div>',17)])])}const u=e(s,[["render",r]]);export{y as __pageData,u as default};
